NIGHT_LOADED({"seed":1067,"generated_at":"2026-10-21T06:00:00Z","chain":[1,4,3,2,5],"frame":{"collector":"J.J.V.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.J.V.","note_final":"Goed opgeborgen. Morgen om negen. — J.J.V.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.J.V.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.J.V.","initials":"J.J.V.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.J.V.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":4,"drawers":[{"id":"1-1","type":"P2","difficulty":3.0868,"rank":0.1503,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"WEV002502","role":"target","render":{"description":"Kolk waarin een molen is verzonken; kolk waarin hooiwagens zijn verdwenen en waarin een koets verdwijnt nadat een stem in het water heeft gevraagd waar de man is, want de tijd is er. Dwaallicht boven kolk betekent dat er iemand zal verdrinken of dat er een huis gebouwd zal worden.","place":null,"prov":"Gr.","year":1962,"code":"SINSAG 0486","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/45349"},"home":"1-1"},{"id":"c2","story_id":"WEV002004","role":"helper","render":{"description":"Licht boven een kolk wordt gezien als voorteken van een ongeluk. Later verdrinkt daar een jongen die zich uit verdriet over een afwijzing door een meisje heeft bedronken.","place":"Mussel","prov":"Gr.","year":1962,"code":"SINSAG 0486","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43322","original":"Achter de boerderij van mijn broer in Mussel was in het \"oal daip\" - de Mussel A - een diepe kolk. Zw. Tuin ziet op een avond boven die kolk een licht branden. Ze vermoedt een komend ongeluk. En dit komt.\n'n Poos later is er een feest. Een jonge man - G.D. - vraagt een meisje, of ze 's avonds met hem uit wil. Ze heeft er geen zin in. \nVan verdriet drinkt hij zich dronken.\nLater heeft 't kind spijt van haar weigering, want D. wordt de andere dag dood uit de kolk gehaald.","lang":"Standaardnederlands","front":"original"},"home":"1-1","geo":[52.955,7.03889]},{"id":"c3","story_id":"WEV006902","role":"helper","render":{"description":"Voorspelling dat bij een vaart iets zal gebeuren, er zijn mensen met een lichtje over een weg gezien. Later is een verdronken jongen 's avonds langs dat pad naar huis gebracht.","place":"Vriescheloo","prov":"Gr.","year":1963,"code":"SINSAG 0486","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43572","original":"Veurloop.\nOabram zag nog meer. Wazzen es n poar jongelu, dei zoln troun-n. \nToun de haile boudel veurmekoar was, woln ze de meubels koopn in Winschootn. t Wicht gung dr op of en de jong zol den in Winschootn bie heur koom-m. Hai bedochde zuk en verdronk zuk in n wieke.  \nMoar, en hier gait mie t om, oal Oabram har al joarn van te veurn zegd:“Doar gunders bie de wieke gebeurt nog es n keer wat. Ik zai dr mensn deur t veld trekn; langs dei loane goan ze en koom-m bie dei boerderij oet. Misschain verdrinkt dr wel aine. Ik zai ook, dat ze n lichie bie zuk hebben.” \nEn net zo is t gebeurd. Bie oavend hebben ze de jong langs t zulfde pad van de wieke noar hoes brocht.","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.06833,7.11389]},{"id":"c4","story_id":"WEV007506","role":"helper","render":{"description":"Voorspelling dat er binnen een dag iemand in een kanaal zal verdrinken komt uit.","place":"Veelerveen","prov":"Gr.","year":1963,"code":"SINSAG 0486","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44134","original":"Toun ze mit t knoal aan t groaven wazzen, moz dr in t leste nog n dam deurstookn wordn.\nWazzen verschaiden manlu bie aan t waark.\nToun kwam dr aine langs, bleef n rukje stoan en zee: \n\"Joa, 't is n mooi knoal worn; t is allaind zo jammer, dat dr binnen vaarntwintig uur ain in verdrinkn mout.\"\n\"Och, doe hest altied wat\", zeden de keerls, en zai smeetn hom mit n schop vol zaand noar de kop.\nMoar kiek, d ander dag, t luip teegn twaalf uur en de mensn woln gau eetn, zee dr n seldoat teegn zien mouder:\n\"Ik goa eerst nog eevn zwemmen heur, veur t eetn.\"\n\"Och, jong, blief hier toch\", zee ze, t is muide nait meer weerd.\"\nHai gung toch hen, mor is best verdronkn.\n\nAal dizze vertelsels binnen woar.\nIk heb ze zulf beleefd.","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.05583,7.12778]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Mussel.","Zoek Barlage op de kaart."],"lock":{"kind":"place","target_geo":[53.0125,7.05556],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Barlage"},"stack":["c1","c2","c3","c4"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.3058,"rank":0.6075,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ046312","role":"member","render":{"description":"Nooit 's nachts middenop de weg rennen: er kan een lijkstoet passeren.","place":"Surhuisterveen","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24424","original":"Wy woarden altyd warskôge: rin noait midden op 'e wei by joun of by nacht, hwant der kin us in lykstaesje passeare.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c2","story_id":"CJ102104","role":"member","render":{"description":"Sommigen moesten 's nachts het bed uit om lijkstoeten te zien. Je moest 's nachts nooit midden op de weg rennen.","place":"Augustinusga","prov":"Fr.","year":1973,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37102","original":"Yn 'e Harkema en yn Stiensgea ha 'k wol guon kend dy't nachts fan bêd moesten om lykstaesjes to sjen.\nMen moest nachts noait midden op 'e wei rinne.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c3","story_id":"KOOIJMAN2266","role":"intruder","render":{"description":"Je werd gewaarschuwd om 's nachts niet in 't wagenspoor of in 't paardenpad te lopen. Want daar kon je de boze geesten tegenkomen.","place":"Heesselt","prov":"Gld.","year":1963,"code":"SINSAG 0333","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/127631","original":"Dat weet ik ook nog. Je werd gewaarschuwd om 's nachts niet in 't wagenspoor of in 't paardenpad te lopen. Want daar kon je de boze geesten tegenkomen.","lang":"Standaardnederlands","front":"original"},"home":"cab:4"},{"id":"c4","story_id":"CJ052415","role":"member","render":{"description":"De verteller vertelt over twee mannen die vaak lijkstoeten zagen. Je moet nooit middenop de weg lopen, omdat een onzichtbare lijkstoet je van de weg af kan drijven.","place":"Surhuisterveen","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25234","original":"Douwe Stavasius fan Grinzer Pein seach lykstaesjes.\nBoardzer Bruining fan Boelensloane ek. Dy leeft noch.\nMen mat noait midden op 'e wei rinne, hwant der kin us in lykstaesje oankomme, sûnder dat men it sjocht. Dan wurde jo fan 'e wei ôfsmiten.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Heesselt hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":4},"on_success":{"trail_note":0,"unlock_cabinet":4,"stack":["c1","c2","c4"]}},{"id":"1-3","type":"R1","difficulty":1.1281,"rank":0.3431,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"Voda_022_16","role":"omen","render":{"description":"Een geestelijke zag zijn eigen begrafenis. Vier mannen met een baar bleven de hele nacht achter hem lopen. Op dezelfde weg stierf hij later.","place":"Eindhoven","prov":"N.-Br.","year":1977,"code":"SINSAG 0481","initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/129749","original":"Een geestelijke uit Oirschot zag eens zijn eigen begrafenis. Op een nacht ging hij van Oirschot naar Best. Daar hoorde hij achter zich iemand lopen. Toen ie omkeek, zag ie vier mannen die een baar droegen. Hij wilde wachten, maar toen hie stil bleef staan, bleven ook de dragers stilstaan. En als ie verder ging, gingen ook de dragers verder. Zo bleven deze vier mannen met de baar de gehele nacht achter de geestelijke lopen. Die was blij dat ie eindelijk in Best aankwam, waar hij van de schrik kon bekomen. Enige tijd later moest de geestelijke weer naar Best. Daar stierf hij plotseling. Toen droeg men het lijk van de geestelijke over dezelfde weg die hij gelopen had toen de dragers met de baar hem volgden.","lang":"Standaardnederlands","front":"description"},"home":"1-3"},{"id":"c2","story_id":"CJ099406","role":"omen","render":{"description":"Als een hond spookhuilt, gaat er binnen 4 dagen in de buurt iemand dood.","place":"Boornbergum","prov":"Fr.","year":1973,"code":"SINSAG 0486","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/36651","original":"As in houn spûkgûlde seinen se, gong der binnen fjouwer dagen ien dea yn net to fiere omtrek.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c3","story_id":"CJ065203","role":"omen","render":{"description":"Een groepje jongens schold eens een oud vrouwtje uit, van wie gezegd werd dat ze een heks was. De vrouw maakte aanstalten alsof ze over de sloot van vier meter heen zou springen, en de jongens gingen er zo snel mogelijk vandoor. Zij moest er 's nachts vaak uit om lijkstoeten te zien.","place":"Twijzelerheide","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/27375","original":"Hjir wenne yn Twizelerheide in âld minske, dat wie Minne Ael, dy gong foar in tsjoenster troch. Hja wie nachts faek warber. Hja wenne oan 'e Swâdde. Dy wie sa'n fjouwer meter breed.\nOp in kear skelden in pear jonges har út, dy wienen oan 'e oare kant fan 'e Swâdde. Doe die se in pear stappen achterút en sei: \"Ik sil jim krije\", krekt as soe se in oanloop nimme.\nDoe naeiden dy jonges hurd út.\nHja moest der nachts út as der in lykstaesje ûnderweis wie.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","4 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":4},"on_success":{"chime":4,"digit":{"value":4,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":3,"drawers":[{"id":"2-1","type":"P1","difficulty":0.9161,"rank":0.8022,"note":"Alle vier noemen ze hetzelfde ding. Dat wordt het etiket. Niet ‘een beest’ schrijven.","cards":[{"id":"c1","story_id":"LYST276","role":"card","render":{"description":"Stiepelteken is ontstaan toen een wit wief de bijl waarmee ze een boerenknecht achtervolgde, in de deurpost van de schuurdeur terecht kwam. De boerenknecht had de witte wieven uitgedaagd door bij een spinvisite een spit te brengen, en er meteen weer vandoor te gaan.","place":"Vasse","prov":"Ov.","year":1937,"code":"SINSAG 0161","initials":"B.J.L.","url":"https://www.verhalenbank.nl/items/show/13620","original":"Op veel plaatsen in Twente hoort men de volgende vertellingen.\nDe Witte Wiefkes hadden eens gasten of spinvisite. De knecht van een boer uit de buurt bracht er het spit heen; en toen als de wind weer terug naar huis te paard. Maar een der witte wiefkes zat hem met een bijl achterna. De knecht was echter eerder thuis. Zij wierp hem echter met de bijl na, die in den stipel (deurstijl achterdeur) bleef zitten en toen riep ze nog: \"Had ik mien eenen schoen zo gauw knupt als m'andren rupt, dan was doe 't gebraad west.\"","lang":"Standaardnederlands; Twents","front":"description"},"home":"2-1"},{"id":"c2","story_id":"LYST280","role":"card","render":{"description":"Een boerenknecht loopt 's nachts langs de Witte Wieve. Omdat hij hen beledigt, achtervolgt een van hen hem. De knecht kan net een huis binnenvluchten. De bijl die het Witte Wief gooide komt terecht in de stiepel.","place":"Goor","prov":"Ov.","year":1937,"code":"SINSAG 0161","initials":"J.W.L.","url":"https://www.verhalenbank.nl/items/show/13624","original":"Witte Wieven waren hier bekend. Men geloofde dat ze ongeluk aanbrachten.\nEen verhaal gaat hier, dat een boerenzoon laat naat huis terugkeerde en langs een plek kwam, waar een wit wief een gebraad aan het spit ronddraaide. De boerenzoon beledigde haar, waarna het witte wief hem met een bijl achterna zette. Gelukkig voor de boerenzoon kon hij nog net de boerderij bereiken, voor het witte wief hem had ingehaald. Maar deze gooide hem nog de bijl achterna, die in de \"stiepel\" bleef zitten.","lang":"Standaardnederlands","front":"description"},"home":"2-1"},{"id":"c3","story_id":"LYST075","role":"card","render":{"description":"Op een bruiloft merkt een van de gasten op dat ze zijn vergeten de witte wieve uit te nodigen. Wanneer iemand spottend de witte wieve roept, wordt er een bijl naar zijn hoofd gegooid. Hij kan net op tijd naar binnen vluchten. De deur vertoont nog altijd de tekenen van de bijl. Het witte wiefke roept dat ze hem wel te pakken had kunnen nemen, als ze haar schoentje niet was verloren.","place":"Zenderen","prov":"Ov.","year":1953,"code":"SINSAG 0161","initials":"M.S.","url":"https://www.verhalenbank.nl/items/show/13289","original":"Parallel met het verhaal van de \"spinvisite\" loopt ook 't verhaal van de \"brulfte\" (bruiloft) waar een van de gasten tegen de \"brulfteneugers\" opmerkt dat hij de \"nögste noabers\" n.l. de \"witte wieve\" heeft vergeten. De \"brulfteneuger\" laat dat niet op zich zitten, gaat naar buiten en nodigt \"de witte wieve\" uit, op spottende toon. Hij wordt onmiddelijk achterna gezeten, vlucht nog net binnenshuis, terwijl hem de bijl nagegooid wordt en 'n snee in de niendeure maakt die nog aan de kleinkinderen van het bruidspaar vertoond wordt. Hier hoort ook weer dezelfde klacht over 't schoentje bij, dat niet was vastgestrikt.","lang":"Standaardnederlands","front":"description"},"home":"2-1"},{"id":"c4","story_id":"ENGELB_13_014","role":"card","render":{"description":"Man die het spit naar berg van de Hunnen brengt wordt daarna achtervolgt door een Hun met een bijl. De man kan de boerderij binnengaan, de Hun gooit hem de bijl na, die in de deurpost terechtkomt.","place":"Rossum","prov":"Ov.","year":1977,"code":"SINSAG 0161","initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/128541","original":"Spit brengen\nG.M.: Ja dee knecht van Scholtn möt dat doan hebn, den hef t spit doar op n Huunboarg bracht en den hef t peard bie zik had en tenminste zoa heb ik t wa es heurd verteln en doe hef he t spit hef he doar henbracht noa n Huunboarg en doe is het der tuskn oet goan, n Huun löaw’k noa met t haandbiel en doe is Schoolt zien knecht bie t Schoolt owwer n onderstn nienduur vlögn en doe hef n Huun hem nog noasmetn en t haandbielkn in in duurnpost smetn\nE.M.: Dat heb ik ok vaak heurd.\nG.M.: Zoa heb ik t vaak heurn verteln.\nE.M.: A’j dat oppervlakkig bekiekt, zo’j zegn. Dat kan hoast geelsnich, mer ja ik heb wa honderd moal heurn verteln.","lang":"Twents","front":"description"},"home":"2-1"}],"hints":["Lees de vier nog eens. Let op wat er in elk van de vier vóórkomt, niet op wat erin gebeurt.","Het is een voorwerp.","Begint met een B. 4 letters."],"lock":{"kind":"word","salt":"0133515b4a0488e2","accepted_hashes":["0e00c262d8eb35f4a13363397b63fa51410ad6e084a081a43ff0f0510a6fba55","3c317cc8707c44228ac926509840df22eb432fd150ad5de47e2fd2622c852174"]},"on_success":{"print_label":true,"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c4"}},{"id":"2-2","type":"P3","difficulty":1.3147,"rank":0.9293,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"KEUNING012603","role":"member","render":{"description":"Op kerkhof zouden 's nachts twee witte vrouwen lopen.","place":"Genum","prov":"Fr.","year":1963,"code":null,"initials":"S.K.","url":"https://www.verhalenbank.nl/items/show/131651","original":"Der waerd ek sein, dat op it tsjerkhôf to Hegebeintum by nacht faek twa wite wiven omrounen.","lang":"Fries","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c2","story_id":"CJ124006","role":"member","render":{"description":"Op een spookplaats dansen 's nachts witte wieven.","place":"Mûnein","prov":"Fr.","year":1979,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32288","original":"Oan 'e dyk to Readtsjerk spûken wite wiven, nei't se seinen. Dy dounsen dêr nachts om.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c3","story_id":"YPFOE070d","role":"member","render":{"description":"De verteller gaat met een paar vrienden op huis aan. Onderweg komen ze een wit meisje tegen dat zich snel voortbeweegt. Ze zweeft in de richting van een huisje. Ze gaan op onderzoek uit. Later heeft zich een oude man opgehangen, en men zegt dat het ermee in verband staat. De dominee staat erg sceptisch tegenover het verhaal.","place":"Goutum","prov":"Fr.","year":1972,"code":null,"initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12149","original":"Wite juffers\nWat ik hjir yn 'e Westerein sels sjoen ha. Dat is no lyn, ik tink sa'n fiif-, seis-, sânenfyftich jier. Myn kammeraat en ik gyngen de jûntiid om in oere of alve stadichoan nei hûs ta. Doe troffen wy in pear jongelju en dy hâlden ús oan. De man sei: 'Sjoch, wat is dêr? Dêr is in famke midden yn 'e sûkerei. By it hûs dêre is it allegearre út en tsjuster, mar hoe kin dan sa'n wyt famke der yn 't lân weze?' Doe seach ik it ek. Ik sei: 'Dan moatte wy dêr ris even sjen'. Mar dat famke avensrarde tige hurd en wy koenen sjen, dat it net gie, mar dat it sweefde. It hie de grutte sawat fan in gewoan famke, en sniewyt. Ik sei: 'No, sille wy ris sjen? …","lang":"Fries","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c4","story_id":"LIJST033","role":"intruder","render":{"description":"Duivel volgt 's avonds een vrouw op weg naar huis.","place":"Baflo","prov":"Gr.","year":1954,"code":null,"initials":"T.W.","url":"https://www.verhalenbank.nl/items/show/14752","original":"I. De duivel\n1. Zijn U verhalen bekend over mensen, die de duivel gezien hebben of omgang met hem hebben gehad (met hem gedanst hebben, met hem kaart hebben gespeeld), of kent U andere verhalen, waarin de duivel een rol speelt?\nGelieve elk verhaal te noteren op een afzonderlijk blad papier en in elk verhaal duidelijk aan te duiden hoe de duivel voorgesteld wordt (met bokshorens, bokspoten, paardenhoeven, sik, staat enz.).\n\nDit hoorde ik als kind; 1899 was het. De dochter van de vrouw die het overkwam vertelde het. Haar moeder was (ook al op leeftijd wel eens laat van de boerderij gekomen waar ze werkte, bij slacht en dergelijke kon het wel eens wat laat in de avond worden. Bij zoo'n gelegenheid was zij eens door de duivel gevolgd. …","lang":"Standaardnederlands; Gronings","front":"original","uncatalogued":true},"home":"cab:5"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Baflo hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c4","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c1","c2","c3"]}},{"id":"2-3","type":"R2","difficulty":1.1331,"rank":0.9492,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"CJ053309","role":"card","render":{"description":"Een man ziet 's nachts plotseling twee witte vrouwen. De twee vrouwen nemen plaats op zijn wagen. De man wordt zo bang, dat hij er snel vandoor gaat.","place":"Ons Belang","prov":"Utr.","year":1968,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25339","original":"Hjir ien út 'e Harkema ried us mei de boerewein op in nacht nei Readskuorre ta. Doe seach er dêr ynienen twa wite froulju foar him. Hy ried dêr mei de hynders lyk op yn.\nDoe kommen dy beide froulju yn 't wyt by him op 'e wein.\nHy woarde sa binaud, dat hy sette sokken en naeide út.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c2","story_id":"CJ044314","role":"card","render":{"description":"Op een nacht zag een man een vrouw in het wit over de tramrails lopen. Hij waarschuwde haar dat de tram eraan kwam. Maar zij verroerde zich niet. Het was een witte juffrouw.","place":"Opende","prov":"Gr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24127","original":"Ik kom us in kear let yn 'e nacht werom fan 't jounpraten. Ik roan op 'e Sintelwei nei Houtigehage. Doe wie dêr in frommes yn 't wyt. Sy wie op 'e raljes. Ik sei tsjin har: \"Frou, jo matte dêr wei gean, hwant de tram is op komst.\"\nMar sy sei neat werom en bleau hwer't se wie. 't Wie in wite juffer.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c3","story_id":"CJ000411","role":"sill","render":{"description":"Drie rondspokende naakte vrouwen zitten een man achterna die zo hard moet lopen dat hij verschrikkelijk moet zweten.","place":"Nijega","prov":"Fr.","year":1965,"code":"SINSAG 0161","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/11550","stain":"Drie"},"home":"2-3"},{"id":"c4","story_id":"CJ013206","role":"card","render":{"description":"Op de Kruisweg in Harkema spoken witte wijven.","place":"Harkema","prov":"Fr.","year":1966,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19522"},"home":"2-3"},{"id":"c5","story_id":"YPFOE143","role":"card","render":{"description":"Een vrouw heeft borstkanker. Ze kan met geen enkel kruid genezen worden. De enige mogelijkheid is om naar Duitsland te gaan, naar de witte nonnen. De nonnen spreken een toverformule uit, en slaan vervolgens een kruis. Na dit enkele malen gedaan te hebben, mag de patiente weer naar huis. Als ze weer thuis is, gaat het langzamerhand beter met haar. Op het laatst komt er een tumor zo groot als een bloemkool uit haar borst vallen. De wond heelt en ze wordt weer helemaal beter.","place":"Burgum","prov":"Fr.","year":1972,"code":"TM 4302","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12993","original":"De wite susters fan Bremen\nIen fan 'e foarâlden fan myn frou—it is al lang Iyn—krige kanker yn 't boarst. Dêr wienen gjin krûden foar woeksen. Der wie noch mar ien mooglikheid: nei Dútslân, nei de wite susters yn Bremen, de wite nonnen. Dêr ha se de pasjinte—it wie in frommis—yn behanneling nommen. Se sprieken in toverformule út. Se seinen (yn 't Dútsk fansels): 'Ik beswar dy yn 'e namme fan de Heit en de Soan en de Hillige Geast, datstû fan har wykst', en al sa mear. En dan sloegen se in krús. Dat ha se in kear of wat dien en doe koe se wer nei hûs ta gean. En doe't se thuskaam, is der súntsjesoan betterskip kommen. Op 't lêst is der in stik guod út kommen as in blomkoal, sokssawat. Dat is út it boarst fallen. …","lang":"Fries","front":"description"},"home":"2-3"},{"id":"c6","story_id":"LYST283","role":"card","render":{"description":"Een dominee moet 's avonds laat door een donker bos terug naar huis lopen. Hij heeft een angstig voorgevoel dat hem iets zal overkomen. En inderdaad, een wit wief vertoont zich aan hem. De dominee zegt tegen de gedaante dat het mag blijven als het door God gestuurt is, maar dat het moet weggaan als het door de duivel gezonden is. De verschijning verdwijnt onmiddellijk.","place":"Ede","prov":"Gld.","year":1937,"code":"SINSAG 0310","initials":"L.C.S.","url":"https://www.verhalenbank.nl/items/show/13627","original":"Witte Wieven\nDominee Detmar, te Ede, kwam laat terug van het bezoek bij een ouderling en moest de Witte Wieven bij Kernhem passeren. Hij voelde zich ongerust, er zou hem iets gebeuren. Toch ging hij. Op het Hooge Dennenboschje verscheen hem een witte juffer. Dominee zei: \"Ben je van God, dan staat, ben je van de duivel, dan gaat.\" En de gedaante verdween.","lang":"Standaardnederlands","front":"description"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een N.","Nijega. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c3","object":"window","text":"Nijega"},"on_success":{"digit":{"value":3,"card":"c3","word":"Drie","stained":"c3"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":7,"drawers":[{"id":"3-1","type":"P5","difficulty":0.8034,"rank":0.875,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"CJ029903","role":"variant","render":{"description":"Een bruidspaar is op weg naar het gemeentehuis, als de aanstaande bruidegom zijn bruid ineens een stuk uit het schort bijt. De man is een weerwolf; het meisje maakt het terstond uit.","place":"Kûkherne","prov":"Fr.","year":1953,"code":"SINSAG 0823","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21918","original":"It gebeurde us dat twa jonge lju yn 'e wein sieten nei 't gemeentehûs ta. Hja soenen dy deis trouwe. Underweis yn 'e wein byt de man har in stik út 'e skelk. Hy wie in wjerwolf. Hja makke it fuort út.","lang":"Fries (Woudfries)","front":"description"},"home":"3-1"},{"id":"c2","story_id":"CJ017409","role":"variant","render":{"description":"Een stelletje staat op het punt van trouwen en maakt een rondritje in de wagen. De aanstaande bruidegom vraagt aan de vrouw of zij een rok voor hem heeft. De vrouw reageert verbaasd maar geeft hem de rok. De man maakt zich snel uit de voeten, maar zijn vrouw volgt hem. Ze ziet dat de man de rok verscheurt met zijn tanden; het schuim staat hem om de mond. De man bekent haar dat hij een weerwolf is en dat hij wel in een doek moest bijten, omdat hij anders een mens zou moeten aanvallen. De vrouw zegt terstond het huwelijk af.","place":"Buitenpost","prov":"Fr.","year":1966,"code":"SINSAG 0823","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20171","original":"Twa jonge lju soenen trouwe. Hja makken de moarns earst in ritsje yn 'e wein.\nUnderweis sei de jonge man: \"Ik mat der even út. Hast ek in read-baeijen rôk?\"\n\"Ja, hwat matst dêr mei?\"\n\"Even brûke.\"\nHy krige de rôk, mar hja folge him stikum. Hy forskuorde de rôk en tjirge him as in wyld beest. It skûm stie him om 'e mûle. It wienen allegearre flarden read guod tusken syn tosken.\n\"Hwat hastû dien?\" frege hja.\n\"Ik sil 't dy sizze. Ik bin in wjerwolf. Nou en dan mat ik hwat forskuorre, oars forskuor ik in minske. Hja rieden togearre wer nei hûs ta.\nDoe sei hja: \"It trouwen giet oer. Ik wol net in keardel ha dy't in wjerwolf is.\"","lang":"Fries (Woudfries)","front":"description"},"home":"3-1"},{"id":"c3","story_id":"CJ044011","role":"variant","render":{"description":"Een van zeven zonen is een weerwolf. Men moet nooit ruzie krijgen met een weerwolf, want dan maakt hij je dood. \nEen meisje naaide altijd bij andere mensen. Haar vrijer vroeg haar eens om een zakdoek. Ze gaf het hem, en buiten verscheurde hij het ding helemaal. Daarna was hij weer normaal. Hij bleek een weerwolf te zijn. Toen heeft het meisje het uitgemaakt.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0823","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24049","original":"Ien fan sawn soannen wie in wjerwolf. As in wjerwolf jin kriget, makket er jin dea, seinen se froeger tsjin ús. Men mat der noait rûzje mei krije, sei in muoike yn 'e Westerein, dan pakke se jo.\nMyn wiif hat in kammeraetske hawn, dy naeide altyd by oare minsken. Dy hie forkearing mei in feint.\nOp in kear wie er by har, doe frege er har om har bûsdoek. Hja hie him de bûsdoek jown, mar doe hied er dy bûsdoek yn alle moster forskuord bûtendoar.\nLetter wie er wer goed west, mar 't is wol útrekke tusken dy beiden. Hwant hy wie in wjerwolf.\nHja hat it sels oan myn wiif forteld. Dat kammeraetske wenne oan it Wyldpaed.","lang":"Fries (Woudfries)","front":"description"},"home":"3-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Friesland werd een voorwerp gezien: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.J.V.","summary":true},"home":"3-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1953.","Op die kaart staat een voorwerp. Welk?"],"lock":{"kind":"word","salt":"0133515b4a0488e2","accepted_hashes":["12696c9eba2b3739d7bccd5cdb170bbeb259dac970b8e576fd546013f04138fc","8a08d7b10acf17bdde96b36b0625848ea025519fcc56278c91b1d357d05a020d","b17dd350708689740556556fa3417da457dc354db11c51abea320f10010b49f2"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"3-2","type":"P3","difficulty":1.1194,"rank":0.5368,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ084112","role":"member","render":{"description":"Één van zeven meisjes is een nachtmerrie en één van zeven jongens een weerwolf.","place":"Rottevalle","prov":"Fr.","year":1971,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32830","original":"Se sizze fan 'e sawn famkes út ien húshâlding is ien in nachtmerje en fan 'e sawn jonges út in húshâlding is ien in wearwolf","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c2","story_id":"CJ018116","role":"intruder","render":{"description":"Op een bepaalde spookplaats spookt een wit wief.","place":"Sumar","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20270","uncatalogued":true},"home":"cab:2"},{"id":"c3","story_id":"CJ101519","role":"member","render":{"description":"Een van zeven dochters is een nachtmerrie; een van zeven zonen is een weerwolf.","place":"Drachtstercompagnie","prov":"Fr.","year":1973,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/36981","original":"Ien fan sawn famkes út ien gesin wie in nachtmerje.\nIen fan sawn jonges út ien gesin wie in wjerwolf.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"CJ085401","role":"member","render":{"description":"Een van zeven broers is een weerwolf. Als hij weer een kuur heeft, moet men hem een oud schort of iets toewerpen. Dat verscheurt hij dan. Als men iemand met de draden uit zijn mond ziet, kan men ervan opaan dat dat een weerwolf is.","place":"Rottevalle","prov":"Fr.","year":1971,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/33002","original":"In wearwolf is in minske, dy forropt de boel. 't Is ien fan sawn jonges (7 bruorren). As er wer sa'n kuer krijt, dat er hwat forskuorre mat, mat men him in âld skelk of sahwathinne tasmite. Us mem sei, dan gebeurde 't wol dat him even letter de triedden ta de mûle úthongen.\nAs men sa'n ien seach, dy't triedden ta de mûle út hie, koe men der fan op oan dat it in wearwolf wie. Dêr koe men se oan herkenne.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een witte vrouw.","De kaart over Sumar hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":2},"on_success":{"trail_note":2,"unlock_cabinet":2,"stack":["c1","c3","c4"]}},{"id":"3-3","type":"R3","difficulty":1.0978,"rank":0.7692,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"TINNEV042","role":"card","render":{"description":"Twee mannen zoeken grasstengels om te snijden. Als ze er geen vinden gaan ze maar naar huis. Wanneer ze uit elkaar zijn gegaan ziet de ene man ineens een grote wolf op zijn pad. De volgende morgen vraagt de andere man aan hem of hij de wolf heeft gezien.","place":"Didam","prov":"Gld.","year":1944,"code":"SINSAG 0823","initials":"A.T.","url":"https://www.verhalenbank.nl/items/show/22388","original":"29.\nPeter ging op een kier met Dorus mieskes sni'je. Mao zi'j konne de gin vinne en wolle daorum weer op huus aan. De weg liep deur een buske. Dorus vroeg aan Peter offe um nao huus sol brenge. \"Loop nao da galg\", antwore Peter en kroap onder de scheibeum nève de weg hèèr.\n\"Hi'j is ter\", riep Dorus um nao. Ienéns stong d'r een grote wolf op de bosweg. Hi'j wol niet op zied gaon. Daorum drèèje Peter de met een flinken boag umhen. Toe e is umkek zag e niks meer. Umdat Peter geld neudig had ginge de 's marges weer op uut um smele te zuke. Ien Kilder was Dorus al met een groten trop aan 't sni'je. Toe hi'j Peter zag riep tem toe: \"Wasse d'r now, of niet?\".","lang":"Liemers","front":"description"},"home":"3-3"},{"id":"c2","story_id":"LYST008","role":"card","render":{"description":"Een boerenknecht haalt iedere nacht precies om twaalf uur een hoepeltje uit de lindeboom. Hij hangt de hoepel om zijn nek en verandert in een weerwolf. Hij loopt een tijdje rond en verscheurt alles wat er in zijn buurt komt. Hierna wordt hij weer gewoon mens. De boer vindt zijn gedrag maar vreemd en vraagt raad aan de pastoor. De pastoor heeft door dat de boerenknecht een weerwolf is, en adviseert de boer om de knecht een boodschap te laten doen waarbij hij nooit om middernacht weer thuis kan zijn. Op de afgesproken nacht haalt de pastoor om middernacht de hoepel uit de boom. De knecht staat onder die boom en ziet alles. Hij vlucht en komt nooit meer terug.","place":"Erp","prov":"N.-Br.","year":1953,"code":"SINSAG 0803","initials":"F.W.J.S.","url":"https://www.verhalenbank.nl/items/show/13222","original":"De Weerwolf\nEen boerenknecht kroop 's nachts klokslag 12 uur in de lindenboom voor de boerderij. Boven in de boom hing voor gewone mensen onzichtbaar een hoepeltje. Dat hing de knecht om zijn hals. Als ie uit de boom geklauterd was, liep ie in de gedaante van een hond weg en verscheurde alles wat hem in de weg kwam. Als ie een tijd zo rondgelopen had, was ie weer gewoon mens. Na een tijd was het de boer, bij wie de weerwolf in dienst was, opgevallen, dat zijn knecht nacht op nacht weg was. Hij ging naar de pastoor en die had het zaakje meteen door. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c3","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c4","story_id":"CJ100830","role":"door","render":{"description":"Van zeven broers is er een een weerwolf. Een weerwolf kan zomaar iemand opeten.","place":"De Westereen","prov":"Fr.","year":1973,"code":"TM 3107","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/36885","original":"Fan sawn bruorren út ien húshâlding is ien in wjerwolf.\nIn wjerwolf koe in oar samar opfrette.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c5","story_id":"VVUNL049","role":"card","render":{"description":"Elke avond na het eten gaat Sjang weg en komt pas heel laat terug. Op een keer volgen ze hem en zien hem iets uit een boom halen en even later was hij een weerwolf. De pastoor wordt gehaald en Sjang moet zijn spullen tevoorschijn halen. Er kwam een schapevacht en een rood stokje met rood lint uit; die worden in de oven verbrand, terwijl drie man Sjang in bedwang houden. Als alles verkoold is, zegt hij verlost te zijn.","place":"Kessel","prov":"L.","year":1952,"code":"SINSAG 0824","initials":"J.N.","url":"https://www.verhalenbank.nl/items/show/35588","original":"De geplaagde herder \n\n't Gebeurde op 'Gravenhof' te Kessel, tussen 1860 en '70. Sjang van de Maas uit Neer was hier scheper; een onnozele, rustige kerel, die niemand kwaad deed, en elke dag zijn schapen hoedde. Maar na een tijdje maakten de boer en de boerin zich over hem ongerust. Elke avond na het eten verdween Sjang plotseling en keerde pas heel laat in de nacht weer huiswaarts. Dit werd zo verdacht dat men op een keer de knaap stilletjes achtervolgde... Men zag toen dat hij tot de holle boom liep, even voorbij het Annakapelletje; daar nam hij iets uit. Na enkele ogenblikken veranderde hij van gedaante, en stoof als schrikaanjagende weerwolf met een geweldige vaart weg. . . …","lang":"Standaardnederlands","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","7 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c4","object":"door","n":7},"on_success":{"digit":{"value":7,"card":"c1"},"stack":["c1","c2","c3","c5"]}}]},{"id":4,"label":"Spoken","digit":2,"drawers":[{"id":"4-1","type":"P4","difficulty":1.648,"rank":0.477,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"CJ015303","role":"top","render":{"description":"Een man heeft zich een avond vermaakt met de vrouwen en stuit op weg naar huis op een grote, donkere hond die hem de weg verspert.","place":"Boornbergum","prov":"Fr.","year":1967,"code":"SINSAG 0333","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19846","half":"top"},"home":"4-1"},{"id":"c2","story_id":"VERHOEFF001001","role":"distractor","render":{"description":"Om middernacht tijdens het waken schommelen van lamp, voetstappen en bons. Uitkomen van voorspelling dat bij begrafenis van het gestorven kind heks komt kijken.","half":"bottom","code":"SINSAG 0478"},"home":"4-1"},{"id":"c3","story_id":"BIJLSMA007505","role":"distractor","render":{"description":"Voerman ziet bij brug iets voor het paard staan, hij zet zijn paard aan, en bij de brug staat een gedaante voor het paard. Man, paard en wagen worden opgetild en in de vaart gesmeten.","half":"bottom","code":"SINSAG 0478"},"home":"4-1"},{"id":"c4","story_id":"KEMP324","role":"distractor","render":{"description":"Het meisje moet een maand lang elke dag een rozenhoedje bidden. Het meisje doet het en de ziel geeft een teken van verlossing: als het meisje op een dag in de kerk zit, ziet zij ineens een verkoolde afdruk in een zakdoek. De zakdoek zou nog altijd in de kerk van Meerssen te zien zijn.","half":"bottom","code":"SINSAG 0402"},"home":"4-1"},{"id":"c5","story_id":"CJ050510","role":"distractor","render":{"description":"Het dier is - als de man zijn ogen even afwendt - plotseling verdwenen. Bij daglicht zijn er geen sporen te zien. Ook de buurman heeft het dier wel eens zien rennen. Het is een spookdier.","half":"bottom","code":"SINSAG 0333"},"home":"4-1"},{"id":"c6","story_id":"KEMP087","role":"distractor","render":{"description":"Maar wie 's nachts op de plek komt, hoort nog het gekerm van de pestlijders en ziet gedaanten dwalen onder de gesel van de zwarte dood.","half":"bottom","code":"SINSAG 0450"},"home":"4-1"},{"id":"c7","story_id":"VODA_005_08","role":"distractor","render":{"description":"Tijdens zijn bezigheden vindt hij een kist met geld. Het gebons stopt echter niet. Dan besluit hij hulp te vragen van een oude vrouw die de kamers met wijwater besprenkelt. Het gebons gaat weg en de eens arme familie heeft nu het geld dat is achtergebleven.","half":"bottom","code":"SINSAG 0401"},"home":"4-1"},{"id":"c8","story_id":"KEMP175","role":"distractor","render":{"description":"Die vertelt haar dat er een schat in de kelder verborgen ligt: twee potten geld, waarvan ze er een aan de kerk moet schenken en de ander zelf mag houden. Vanaf nu zijn de vrouw en haar man rijk en zij verkopen hun winkel.","half":"bottom","code":"SINSAG 0401"},"home":"4-1"},{"id":"c9","story_id":"LYST018","role":"distractor","render":{"description":"De man vraagt keer op keer aan de dronkelap: \"waar moet ik hem neerleggen?\", waarop de zuipschuit antwoordt dat hij de steen maar moet neerleggen waar hij hem gekregen heeft. Op datzelfde moment verdwijnt de drager van de grenssteen.","half":"bottom","code":"SINSAG 0404"},"home":"4-1"},{"id":"c10","story_id":"CJ015303","role":"bottom","render":{"description":"Piter wacht eerst een poosje of de hond vanzelf weggaat. Als het dier blijft zitten, besluit hij er gewoon langs te gaan. Dan ligt hij plotseling met de hond in de sloot. De hond is even later ineens verdwenen en Piter rent doodsbenauwd naar huis. Het was een spookdier.","half":"bottom","code":"SINSAG 0333"},"home":"4-1"},{"id":"c11","story_id":"BIJLSMA008901","role":"distractor","render":{"description":"De strandjutters hakken echter haar beide handen af om de ringen mee te nemen en de vrouw verdrinkt. 's Nachts zien schippers de vrouw bij de paal ronddolen, waardoor de moord niet wordt vergeten.","half":"bottom","code":"SINSAG 0450"},"home":"4-1"},{"id":"c12","story_id":"VODA_023_06","role":"distractor","render":{"description":"De ronddolende geest van de ridder lokt mensen het Dolle Moer in. Volgens de voorspelling wordt het lijk van de ridder gevonden, in de vorm van \no.m. een vergulde zilveren helm.","half":"bottom","code":"SINSAG 0450"},"home":"4-1"},{"id":"c13","story_id":"CJ101213","role":"distractor","render":{"description":"Het was een plaagbeest, en het ging pas weg toen hij roggebrood te voorschijn haalde.","half":"bottom","code":"SINSAG 0333"},"home":"4-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het onderste stuk noemt ‘hond’ opnieuw.","Het nummer is SINSAG 0333. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c10"},"on_success":{"fuse":["c1","c10"],"stack":["c1","c10"]},"found_card":{"card":"c10"}},{"id":"4-2","type":"P3","difficulty":1.1065,"rank":0.515,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"SINBRABSAG078","role":"member","render":{"description":"In Aalst zag de dochter van een boerin een geest, terwijl ze de koe aan het melken was. Ze was erg bang en de volgende dag ging de knecht mee. Ook hij zag de geest. De geest kwam elke avond dichterbij en de pastoor zei dat ze aan de geest moesten vragen wat zijn begeerten zijn. De boerin, knecht en de dochter vroegen de geest naar zijn begeerten en hij vertelde dat hij een belofte had gedaan om een bedevaart te maken naar Kevelaar, maar die niet meer was nagekomen. Ze besloten om met z'n allen de bedevaart te maken. Na de reis was de geest verlost en kon hij naar de hemel.","place":"Voldijn","prov":"N.-Br.","year":1933,"code":null,"initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/46713","original":"No. 78. Iederen avond ging de dochter van een boer uit Aalst met een paar meiden de koeien melken, tot zij op zekeren avond aan den rand van een bosch, op flinken afstand, een witte gedaante zag verschijnen. Ze werd bang en liep naar huis, zonder de koeien verder te melken. Ze kon niet spreken van angst en schrik, omdat ze niet wist wat 't was, en kwam hijgend van 't loopen thuis aan. De huisgenooten vroegen direct wat er aan de hand was, en toen zei ze, na tot bedaren gekomen te zijn, dat 't kon gaan zooals 't wilde, maar ze ging niet meer alleen melken, zoo was ze geschrokken. Den volgenden avond ging de knecht mee, omdat ze alleen niet meer wilde. Ze zagen dezelfde gedaante weer, maar nu kwam ze veel dichter bij. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c2","story_id":"SINBRABSAG080","role":"member","render":{"description":"Een arme bezembinder zag de geest van zijn vader, die kort geleden gestorven was, op de kruiwagen zitten. Zijn vader vertelde hem dat hij een bedevaart moest maken en brood aan de armen moest geven, zijn vader had namelijk een belofte gedaan die hij niet was nagekomen. Na deze woorden verdween zijn vader.","place":"Eersel","prov":"N.-Br.","year":1933,"code":null,"initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/46715","original":"No. 80. Omstreeks 1840 ging de arme bezembinder R. v. G. uit Eersel hei snijden. Nadat hij zijn vracht op de kruiwagen geladen had, rustte hij in de Zanddreef wat uit. Toen hij zijn tocht wilde voortzetten zat de geest van zijn vader, die voor kort gestorven was, op z'n kruiwagen. Hij beval zijn zoon om een beevaart te doen en den armen een brood te geven, want hij had tijdens zijn leven, een belofte niet nagekomen. Daarop verdween de geest, zonder een spoor achter te laten. 2)","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c3","story_id":"SINBRABSAG081","role":"member","render":{"description":"De geest van de pastoor vraagt aan een vroom persoon of zij een goed werk voor hem wilt doen, zodat hij in de hemel kan komen.","place":"Westerhoven","prov":"N.-Br.","year":1933,"code":null,"initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/46716","original":"No. 81. Het gebeurde op het gehucht Loveren, anderen zeggen in het braambosch, onder Westerhoven. De pastoor was gestorven, en zijn geest verscheen aan een vroom kwezelken, en verzocht haar spoedig een goed werk voor hem te laten doen, dan zou hij zalig worden.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c4","story_id":"CJ039817","role":"intruder","render":{"description":"Man vraagt aan zijn verkering om een zakdoek, en verdwijnt daarmee. Bij terugkomst hangen rode draden van de zakdoek tussen zijn tanden. Hij bekent een weerwolf te zijn die af en toe iets moet verscheuren, en had om een zakdoek gevraagd om haar niet te verscheuren.","place":"Harkema","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/23534","original":"Der wienen in feint en in faem, dy wienen togearre út to riden.\nUnderweis lei de feint de swipe del en hy liet it hynder stilstean.\nDe faem sei tsjin 'e feint: \"Hwat silstû?\"\n\"Jow my de bûsdoek\", sei er. Doe joech se him in reade bûsdoek. Dêr gong er mei fuort.\nDoe't er in skoftsje fuort west hie, kom er werom. Doe hied er de reade triedden fan 'e bûsdoek tusken de tosken hingjen.\n\"Hwat hastû dien?\" sei se.\nDoe hied er bikend dat er in wjerwolf wie. Hy moest nou en dan hwat forskuorre. Dêrom hied er om 'e bûsdoek frege, oars hied er har forskuorre matten.\nDoe hat dy faem de forkearing gau út makke.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:3"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een weerwolf.","De kaart over Harkema hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c4","cabinet":3},"on_success":{"trail_note":1,"unlock_cabinet":3,"stack":["c1","c2","c3"]}},{"id":"4-3","type":"R4","difficulty":1.1385,"rank":0.5,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"CJ096704","role":"top","render":{"description":"Op een avond waren de man van de vertelster en zijn neef naar herberg ' De laatste Stuver' geweest.","place":"Buitenpost","prov":"Fr.","year":1973,"code":"SINSAG 0333","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/36136","half":"top"},"home":"4-3"},{"id":"c2","story_id":"BOEKV147","role":"half","render":{"description":"De spoken halen een ketel met gouden munten omhoog en verstoppen hem weer. 's Ochtends vraagt de soldaat de knecht om mee te helpen graven. Bij de hooiberg vinden ze de ketel met goud en nemen die mee. 's Nachts komen de spoken weer graven, maar vinden niets en keren niet meer terug. De boer is tevreden en biedt de soldaat onderdak en beloning. De soldaat accepteert het onderdak, maar geld heeft hij inmiddels genoeg.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c3","story_id":"CJ101206","role":"half","render":{"description":"Ze vroeg of het beest van de Heer of van Satan kwam. Als het van de duivel kwam moest het ophoepelen. Het beest verdween.","half":"bottom","code":"SINSAG 0333"},"home":"4-3"},{"id":"c4","story_id":"CJ096704","role":"bottom","render":{"description":"Toen ze op een brug stonden, zagen ze een dier over de wei komen. Het dier was roetzwart en zo groot als een koe. Het had de gedaante van een hond. Het beest keek de twee mannen aan. Die werden zo bang dat ze zich snel uit de voeten maakten.","half":"bottom","code":"SINSAG 0333","stain":"twee"},"home":"4-3"},{"id":"c5","story_id":"DYKFRIES2153","role":"half","render":{"description":"Toen ze gewaarschuwd werd voor het spookveulen, beweerde ze dat ze het dier haar kousenband in de bek zou doen en op het beest naar huis zou rijden. Toen ze het dier echter daadwerkelijke ontmoette, schrok ze hevig en rende ze naar huis.","half":"bottom","code":"SINSAG 0333"},"home":"4-3"},{"id":"c6","story_id":"CJ046110","role":"half","render":{"description":"De winkelier gelooft het niet, maar wordt kort daarop opgeschrikt door de geest van de overleden echtgenoot.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"},{"id":"c7","story_id":"KOOIJMAN1256","role":"half","render":{"description":"Een van die boeren kon toveren en die was in de nacht met paard en wagen in de Oude Straat, toen er ineens twee katten voorsprongen.","half":"bottom","code":"SINSAG 0478"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘man’ opnieuw.","Het nummer is SINSAG 0333. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c4","object":"typewriter"},"on_success":{"fuse":["c1","c4"],"type_line":"Verteller: de vorige assistent.","digit":{"value":2,"card":"c1","word":"twee","stained":"c4"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
